WITH valid AS (SELECT id, order_id, amount, paid_at, status, LENGTH(status) AS status_length FROM payments WHERE method = 'bank_transfer' AND order_id IS NOT NULL), with_gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_session FROM valid), sessionized AS (SELECT id, amount, paid_at, status, SUM(is_new_session) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT CASE WHEN burst_id >= 7 THEN 'LARGE' ELSE 'SMALL' END AS burst_id_tier, CASE WHEN amount >= 1770 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, burst_id, ROUND(AVG(amount), 2) AS avg_amount, MAX(paid_at) AS last_paid_at, COUNT_IF(status = 'FAILED') AS failed_events, ROUND(AVG(burst_id), 2) AS avg_burst_id, COUNT(DISTINCT status) AS distinct_status, GROUPING_ID() AS grouping_level FROM sessionized GROUP BY ROLLUP (CASE WHEN burst_id >= 7 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN amount >= 1770 THEN 'HIGH' ELSE 'LOW' END, burst_id) ORDER BY burst_id DESC
